import calendar
from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split(" ")
    kind = parts[0]
    out: list[str] = []

    def emit(d: date) -> bool:
        if d >= s:
            out.append(d.isoformat())
        return len(out) >= count

    if kind == "DAILY":
        k = int(parts[1])
        d = s
        while True:
            if emit(d):
                break
            d += timedelta(days=k)

    elif kind == "WEEKLY":
        k = int(parts[1])
        days = sorted({_WD[x] for x in parts[2].split(",")})
        monday = s - timedelta(days=s.weekday())
        w = 0
        while True:
            base = monday + timedelta(weeks=w * k)
            done = False
            for wd in days:
                d = base + timedelta(days=wd)
                if d < s:
                    continue
                if emit(d):
                    done = True
                    break
            if done:
                break
            w += 1

    elif kind == "MONTHLY" and len(parts) == 3:
        k = int(parts[1])
        dd = int(parts[2])
        y, m = s.year, s.month
        mi = 0
        while True:
            if mi % k == 0:
                last = calendar.monthrange(y, m)[1]
                if dd == -1:
                    day = last
                else:
                    day = dd
                if 1 <= day <= last:
                    if emit(date(y, m, day)):
                        break
            m += 1
            if m > 12:
                m = 1
                y += 1
            mi += 1

    elif kind == "MONTHLY":
        k = int(parts[1])
        n = int(parts[2])
        wd = _WD[parts[3]]
        y, m = s.year, s.month
        mi = 0
        while True:
            if mi % k == 0:
                last = calendar.monthrange(y, m)[1]
                if n == -1:
                    d = date(y, m, last)
                    while d.weekday() != wd:
                        d -= timedelta(days=1)
                else:
                    first = date(y, m, 1)
                    offset = (wd - first.weekday()) % 7
                    day = 1 + offset + 7 * (n - 1)
                    if day > last:
                        d = None
                    else:
                        d = date(y, m, day)
                if d is not None and emit(d):
                    break
            m += 1
            if m > 12:
                m = 1
                y += 1
            mi += 1

    elif kind == "YEARLY":
        k = int(parts[1])
        mm, dd = (int(x) for x in parts[2].split("-"))
        y = s.year
        while True:
            if (y - s.year) % k == 0:
                if mm == 2 and dd == 29 and not calendar.isleap(y):
                    pass
                else:
                    if emit(date(y, mm, dd)):
                        break
            y += 1

    return out
